function textForVariant(variant: string) {
  const shared = {
    recipientLabel: "This certificate is presented to",
    issuerName: "Avery House Academy",
    footerText: "Academy seal",
    dateText: "Issued 14 October 2024",
    kickerText: "Merit / press",
    signatureTitle: "Director of studies",
    signatureText: "Signature",
    stampLabel: ["navy", "art-deco"].includes(variant) ? "★" : variant === "ribbon" ? "MP" : ["burgundy", "crimson"].includes(variant) ? "Merit press" : "Official seal",
    showLogo: true,
    showAcademyName: true,
    showBodyCopy: true,
    showStamp: true,
    stamp: "",
    stampX: 87,
    stampY: 82,
    stampWidth: 14,
  };
  const copy: Record<string, { certificateTitle: string; bodyCopy: string }> = {
    ivory: { certificateTitle: "Certificate of Completion", bodyCopy: "In recognition of completing the Avery House Academy programme with distinction." },
    burgundy: { certificateTitle: "Certificate of Appreciation", bodyCopy: "For the care, curiosity, and generous contribution brought to our learning community." },
    navy: { certificateTitle: "Certificate of Achievement", bodyCopy: "For exceptional focus and a standard of work that sets a strong example for others." },
    ribbon: { certificateTitle: "Certificate of Excellence", bodyCopy: "For achieving a remarkable result through patience, practice, and purpose." },
    geometric: { certificateTitle: "Certificate of Participation", bodyCopy: "An enthusiastic contribution to the Avery House Academy workshop series." },
    green: { certificateTitle: "Certificate of Merit", bodyCopy: "A thoughtful and consistent commitment to learning, craft, and community." },
    rose: { certificateTitle: "A moment to celebrate", bodyCopy: "For showing up with courage, generosity, and a joy for the work." },
    slate: { certificateTitle: "Certificate of Distinction", bodyCopy: "For work marked by clarity, discipline, and an uncommon attention to detail." },
    "art-deco": { certificateTitle: "Honors certificate", bodyCopy: "This honour is conferred for an accomplished season of study and service." },
    crimson: { certificateTitle: "Scholar's award", bodyCopy: "For intellectual generosity and an enduring commitment to asking better questions." },
    botanical: { certificateTitle: "Certificate of growth", bodyCopy: "For steady progress, generous collaboration, and a beautiful willingness to begin again." },
    linen: { certificateTitle: "Certificate of completion", bodyCopy: "For completing the prescribed course of study at Avery House Academy." },
  };
  return { ...shared, ...(copy[variant] ?? copy.ivory) };
}

